# analyze_logs.py
import argparse
import hashlib
import json
from collections import Counter, defaultdict
from datetime import datetime, timedelta, timezone
from pathlib import Path

REQUIRED = {
    "auth": ["timestamp", "event_type", "user", "source_ip", "outcome"],
    "endpoint": ["timestamp", "event_type", "user", "host", "action"],
    "network": ["timestamp", "event_type", "source_ip", "dest_ip", "action"],
}

def parse_ts(value):
    dt = datetime.fromisoformat(value.replace("Z", "+00:00"))
    if dt.tzinfo is None:
        raise ValueError("naive timestamp: " + value)
    return dt.astimezone(timezone.utc)

def read_jsonl(path, source):
    events, errors = [], []
    with open(path, encoding="utf-8") as fh:
        for line_no, line in enumerate(fh, 1):
            if not line.strip():
                continue
            try:
                event = json.loads(line)
                missing = [k for k in REQUIRED[source] if not event.get(k)]
                if missing:
                    errors.append(f"{path}:{line_no}: missing {','.join(missing)}")
                    continue
                event["_source"] = source
                event["_line"] = line_no
                event["_event_time"] = parse_ts(event["timestamp"])
                events.append(event)
            except Exception as exc:
                errors.append(f"{path}:{line_no}: {exc}")
    return events, errors

def sha256(path):
    h = hashlib.sha256()
    with open(path, "rb") as fh:
        for chunk in iter(lambda: fh.read(1024 * 1024), b""):
            h.update(chunk)
    return h.hexdigest()

def find_auth_bursts(events, window_minutes=5, minimum_failures=3):
    failures = defaultdict(list)
    successes = defaultdict(list)
    for e in events:
        if e.get("event_type") != "auth":
            continue
        ip = e.get("source_ip")
        if e.get("outcome") == "failure":
            failures[ip].append(e)
        elif e.get("outcome") == "success":
            successes[ip].append(e)
    findings=[]
    window=timedelta(minutes=window_minutes)
    for ip, items in failures.items():
        items.sort(key=lambda e:e["_event_time"])
        for right in range(len(items)):
            left=right
            while left>0 and items[right]["_event_time"]-items[left-1]["_event_time"]<=window:
                left-=1
            if right-left+1>=minimum_failures:
                start=items[left]["_event_time"]
                end=items[right]["_event_time"]
                later=[s for s in successes.get(ip,[]) if end <= s["_event_time"] <= end+window]
                findings.append({"type":"auth_failure_burst","source_ip":ip,"failure_count":right-left+1,"start":start.isoformat(),"end":end.isoformat(),"later_successes":len(later)})
                break
    return findings

def main():
    ap=argparse.ArgumentParser()
    ap.add_argument("--auth"); ap.add_argument("--endpoint"); ap.add_argument("--network"); ap.add_argument("--output",default="report.json")
    args=ap.parse_args()
    inputs=[("auth",args.auth),("endpoint",args.endpoint),("network",args.network)]
    all_events=[]; errors=[]; used=[]
    for source,path in inputs:
        if not path: continue
        events,errs=read_jsonl(path,source); all_events.extend(events); errors.extend(errs); used.append((source,path))
    all_events.sort(key=lambda e:(e["_event_time"],e["_source"],e["_line"]))
    counts=Counter(e["_source"] for e in all_events)
    report={
        "generated_at":datetime.now(timezone.utc).isoformat(),
        "quality":{"event_counts":dict(counts),"error_count":len(errors),"errors":errors},
        "findings":find_auth_bursts(all_events),
        "timeline":[{"timestamp":e["_event_time"].isoformat(),"source":e["_source"],"event_type":e["event_type"],"user":e.get("user"),"host":e.get("host"),"source_ip":e.get("source_ip"),"dest_ip":e.get("dest_ip"),"action":e.get("action"),"outcome":e.get("outcome"),"line":e["_line"]} for e in all_events],
        "evidence_manifest":[{"path":path,"sha256":sha256(path),"size":Path(path).stat().st_size} for _,path in used],
        "limitations":["Synthetic lab data does not prove real-world maliciousness.","Correlation matches are candidate findings requiring validation.","Missing telemetry reduces confidence and is reported rather than silently ignored."]
    }
    Path(args.output).write_text(json.dumps(report,indent=2),encoding="utf-8")
    print(json.dumps(report,indent=2))

if __name__ == "__main__": main()
